/*
 * libmstflint_sdk.so export list (GNU ld version script).
 *
 * The SDK's ABI is exactly the functions declared in the public
 * <mft_sdk/*.h> headers, listed below by header. "local: *" makes every
 * other symbol linked into the library local: mtcr, reg_access,
 * tools_layouts, adb_parser, mlxlink, the bundled jsoncpp, spdlog and fmt,
 * and std:: template instances. Applications cannot see or override them.
 *
 * Adding an API function: declare it in a public header AND list it below.
 * A function that is not listed here is not exported.
 *
 * The i2c entries are defined only with --enable-i2c; GNU ld ignores a listed
 * symbol that is not defined (lld >= 16 needs --undefined-version).
 */
{
    global:
        /* mft_sdk_amber.h */
        mstFreeAmberReport;
        mstGetAmberJson;
        mstGetAmberReport;
        /* mft_sdk_cr_space_access.h */
        mstReadCRSpace;
        mstWriteCRSpace;
        /* mft_sdk_discovery.h */
        mstDiscoverAvailableDevices;
        mstFreeDiscoveredDevices;
        mstFreePCIeSubInterfaces;
        mstGetAvailablePCIeSubinterfaces;
        mstGetDeviceHandle;
        mstGetDeviceHandleByBDF;
        mstGetDeviceHandleByFwctlDeviceName;
        mstGetDeviceHandleWithI2cSecondary;
        mstReleaseDeviceHandle;
        /* mft_sdk_errors.h */
        mstGetInitErrorString;
        mstGetLastErrorString;
        mstGetSyndrome;
        /* mft_sdk_hca_caps.h */
        mstFreeHcaCapabilitiesArray;
        mstFreeHcaCapabilitiesMetadata;
        mstFreeHcaCapabilityMap;
        mstGetCapabilitiesByType;
        mstGetCapabilityTypesList;
        mstGetCapabilityValue;
        mstInitHcaCapabilityMap;
        mstQueryHcaCapability;
        mstSetCapabilityValue;
        mstSetHcaCapability;
        /* mft_sdk_i2c_access.h */
        mstGetI2cSecondary;
        mstSetI2cSecondary;
        /* mft_sdk_icmd.h */
        mstSendIcmd;
        /* mft_sdk_reg_access.h */
        mstFreePrmRegisterExpandedMetadata;
        mstFreePrmRegisterMap;
        mstFreePrmRegisterMetadata;
        mstFreePRMRegisterNamesArray;
        mstGetPRMRegisterField;
        mstGetRegisterExpandedMetadata;
        mstGetRegisterMetadata;
        mstInitRegisterMap;
        mstSendPRMRegister;
        mstSendRawPRMRegister;
        mstSetPRMRegisterField;
        mstShowAllPRMRegisters;
        /* mft_sdk_resource_dump.h */
        mstDumpResource;
        mstDumpResourceToBuffer;
        mstDumpResourceToFile;
        mstFreeResourceDump;
        mstFreeResourceMenu;
        mstGetResourceMenu;
        /* mft_sdk_telemetry.h */
        mstFreeJsonString;
        mstFreeTextString;
        mstGetCableDDMInfo;
        mstGetCountersInfo;
        mstGetFecHistogram;
        mstGetModuleInfo;
        mstGetTelemetryJson;
        mstGetTelemetryOperationalInfo;
        mstGetTelemetryText;
        mstGetTroubleShootingInfo;
        /* mft_sdk_temperature.h */
        mstGetDeviceTemperature;
    local:
        *;
};
